tasks.loopCondition:
// agent_loop condition: returns true to run another iteration.
// Stop when next_action picked "stop" (record_result then says done), or at maxIterations, a cap that
// prepare_agent_context sets above the worst case, so it only ends a run if something is broken.
function shouldRunAgain() {
  const recorded = $.record_result_ref || {};
  const result = recorded.result || {};
  if (result.done) {
    return false;
  }
  return $.agent_loop_ref.iteration < $.maxIterations;
}

shouldRunAgain();

inputParameters.expression:
// next_action: runs first in every iteration of agent_loop and picks one action: scan the next queued
// version, ask the LLM to propose versions ("propose"), or stop. When nothing is queued, it first
// reviews every choice against the rules below and writes the status lines the LLM reads.
//
// Inputs:  $.stateText         the planner's state, from the workflow variable stateText (null in the
//                              first iteration, when it starts from the current dependencies)
//          $.dependenciesText  the current dependencies, as JSON text, e.g. {"express": "4.17.1"}
//          $.maxAnswers        the most LLM answers per run (3 if it doesn't arrive)
// Output:  action              "scan", "propose" or "stop"
//          arguments           for "scan": {packageName, packageVersion}, the arguments of POST_scan
//          statusText          for "propose": what the LLM reads, one status line per dependency, e.g.
//                              lodash 4.17.20: must change (own: 2 HIGH, fixed in 4.18.0). Choice: lodash@4.18.0,
//                              rejected: deprecated ("Bad release. ..."). Candidates: lodash@4.18.1 (npm latest).
//          stateText           the state with this iteration's review; record_result adds the result
//
// The state (JSON text): dependencies [{name, version}]; queue [{packageName, packageVersion}], the
// versions still to scan; rounds [{round, scans, statusText, answer}]; choices {dependency:
// {packageName, packageVersion, reason, note}}, which start as the current versions; verdicts
// {"lodash@4.18.0": "deprecated (...)"}, "" for an accepted version; review {dependency: {choice,
// status, accepted, problem, fellBack}}; lastAccepted {dependency: the last choice a review accepted};
// answers; lastAnswer {usable, queued}; iterations; stopReason.
//
// The rules:
// - A version is accepted when its scan has data from deps.dev and OSV.dev, the version isn't
//   deprecated, its package isn't deprecated as a whole, and it has no HIGH or CRITICAL advisory of
//   its own. Advisories in its dependencies don't block it, because the plan overrides them.
// - Each current dependency gets a status from its own scan: "must be replaced" (the whole package is
//   deprecated, or a HIGH or CRITICAL advisory of its own has no fix), "must change" (the version is
//   deprecated, or has a HIGH or CRITICAL advisory of its own), "couldn't be checked" (its scan
//   failed or had no data) or "acceptable as is". Only "must be replaced" allows another package.
// - Stop when every choice is accepted after at least one answer, after maxAnswers answers, or when a
//   usable answer brought nothing new to scan. Otherwise ask the LLM, which always answers once, since
//   it may still upgrade a version that is acceptable as is.
// - On stopping, a rejected choice falls back to the dependency's last accepted choice, if it had one,
//   e.g. back to @strapi/strapi@5.58.0 after 5.60.0 came back without deps.dev data.
//
// Notes on Conductor:
// - The last line calls nextAction(); what it returns becomes the task output.
//   Everything else is inside functions, because a top-level const or let can fail when
//   Conductor reuses a script context.
// - Text is joined with + because Conductor treats a dollar sign followed by a brace in a task
//   input as a workflow reference, which rules out JavaScript template literals.
// - Both inputs arrive as JSON text, so JSON.parse gives plain JavaScript values.

function parseJson(text, fallback) {
  if (!text) {
    return fallback;
  }
  try {
    return JSON.parse(String(text));
  } catch (e) {
    return fallback;
  }
}

// The state for the first iteration: every current version queued, and kept as the starting choice.
function startState(dependencies) {
  const state = {
    dependencies: [],
    queue: [],
    rounds: [{ round: 1, scans: [], statusText: "", answer: null }],
    choices: {},
    verdicts: {},
    review: {},
    lastAccepted: {},
    answers: 0,
    lastAnswer: null,
    iterations: 0,
    stopReason: ""
  };
  for (const name of Object.keys(dependencies)) {
    const version = String(dependencies[name]);
    state.dependencies.push({ name: name, version: version });
    state.queue.push({ packageName: name, packageVersion: version });
    state.choices[name] = { packageName: name, packageVersion: version, reason: "the current version", note: "" };
  }
  return state;
}

// Every scan so far, by "name@version".
function scansById(state) {
  const scans = {};
  for (const round of state.rounds) {
    for (const scan of round.scans) {
      scans[scan.packageName + "@" + scan.packageVersion] = scan;
    }
  }
  return scans;
}

// Why a scan proves nothing, or "" if it has the data a decision needs.
function dataProblem(scan) {
  if (!scan) {
    return "not scanned yet";
  }
  const result = scan.result || {};
  if (result.error) {
    return "its scan failed (" + String(result.error).substring(0, 150) + ")";
  }
  if (result.dependencies && result.dependencies.total === undefined) {
    return "its scan had no deps.dev data (the version may be too new for deps.dev, or may not exist, or deps.dev may be failing)";
  }
  if (typeof result.advisories === "string") {
    return "its scan had no OSV.dev data";
  }
  if (result.warning) {
    return "its scan came back with a warning: " + result.warning;
  }
  return "";
}

function isSevere(advisory) {
  const severity = String(advisory.severity || "").toUpperCase();
  return severity === "HIGH" || severity === "CRITICAL";
}

// How many of the version's own advisories are HIGH or CRITICAL.
function severeCount(result) {
  let count = 0;
  for (const advisory of result.advisories || []) {
    if (isSevere(advisory)) {
      count++;
    }
  }
  return count;
}

// ", fixed in 4.18.0", ", fixed in 5.0.0 (new major)", ", with no fix" or "", from the scan's upgrade.
function fixText(upgrade) {
  const status = (upgrade || {}).status;
  if (status === "same_major") {
    return ", fixed in " + upgrade.recommendedVersion;
  }
  if (status === "major_upgrade") {
    return ", fixed in " + upgrade.recommendedVersion + " (new major)";
  }
  if (status === "no_fix") {
    return ", with no fix";
  }
  if (status === "no_single_fix") {
    return ", with no single version fixing them all";
  }
  return "";
}

// Why a version is rejected, or "" if it's accepted (see the rules above).
function rejection(scan) {
  const problem = dataProblem(scan);
  if (problem !== "") {
    return problem;
  }
  const result = scan.result;
  const deprecation = result.deprecation || {};
  if (deprecation.latestDeprecated === true) {
    return "the whole package is deprecated";
  }
  if (deprecation.thisVersion === true) {
    let text = "deprecated";
    if (deprecation.reason) {
      text += " (\"" + deprecation.reason + "\")";
    }
    return text;
  }
  const severe = severeCount(result);
  if (severe > 0) {
    return severe + " HIGH or CRITICAL " + (severe === 1 ? "advisory" : "advisories") + " of its own" + fixText(result.upgrade);
  }
  return "";
}

// The status of a current dependency, from its own scan (see the rules above).
function statusOf(scan) {
  if (dataProblem(scan) !== "") {
    return "couldn't be checked";
  }
  const result = scan.result;
  const deprecation = result.deprecation || {};
  const severe = severeCount(result);
  const status = (result.upgrade || {}).status;
  if (deprecation.latestDeprecated === true || (severe > 0 && (status === "no_fix" || status === "no_single_fix"))) {
    return "must be replaced";
  }
  if (deprecation.thisVersion === true || severe > 0) {
    return "must change";
  }
  return "acceptable as is";
}

// What a scan found, in a few words, e.g. "own: 1 MODERATE, 1 LOW, fixed in 4.20.0; 6 HIGH or
// CRITICAL in dependencies, fixable by overrides"
function describeFacts(scan) {
  const problem = dataProblem(scan);
  if (problem !== "") {
    return problem;
  }
  const result = scan.result;
  const parts = [];
  const deprecation = result.deprecation || {};
  if (deprecation.latestDeprecated === true) {
    parts.push("the whole package is deprecated");
  } else if (deprecation.thisVersion === true) {
    parts.push("deprecated");
  }

  // e.g. "own: 2 HIGH, fixed in 4.18.0"
  const order = ["CRITICAL", "HIGH", "MODERATE", "LOW"];
  const counts = {};
  let other = 0;
  for (const advisory of result.advisories || []) {
    const severity = String(advisory.severity || "").toUpperCase();
    if (order.indexOf(severity) >= 0) {
      counts[severity] = (counts[severity] || 0) + 1;
    } else {
      other++;
    }
  }
  const own = [];
  for (const severity of order) {
    if (counts[severity]) {
      own.push(counts[severity] + " " + severity);
    }
  }
  if (other > 0) {
    own.push(other + " of unknown severity");
  }
  if (own.length > 0) {
    parts.push("own: " + own.join(", ") + fixText(result.upgrade));
  }

  // e.g. "12 HIGH or CRITICAL in dependencies, fixable by overrides"
  const dependencies = result.dependencies || {};
  if (dependencies.highOrCritical > 0) {
    const unfixed = dependencies.unfixedHighOrCritical || [];
    let text = dependencies.highOrCritical + " HIGH or CRITICAL in dependencies";
    if (unfixed.length > 0) {
      text += ", " + unfixed.length + " of those dependencies with no fix (" + unfixed.slice(0, 3).join(", ") + ")";
    } else {
      text += ", fixable by overrides";
    }
    parts.push(text);
  }
  if (parts.length === 0) {
    return "no known advisories";
  }
  return parts.join("; ");
}

// Versions the scans point to that haven't been scanned or queued yet: each scanned version's
// recommended upgrade, and npm's latest version unless it's deprecated, for the current package and
// the chosen one. e.g. ["lodash@4.18.1 (npm latest)"]. A replacement package's npm latest comes
// first: with no current version to stay close to, it's the one to try (in one run the LLM followed
// axios 0.21.4's fixes up the old 0.x line instead of trying 1.21.0).
function candidatesFor(state, dependency, scans) {
  const choice = state.choices[dependency];
  const packages = [dependency];
  if (choice.packageName !== dependency) {
    packages.push(choice.packageName);
  }
  const taken = {};
  for (const id of Object.keys(scans)) {
    taken[id] = true;
  }
  for (const item of state.queue) {
    taken[item.packageName + "@" + item.packageVersion] = true;
  }
  const candidates = [];
  for (const id of Object.keys(scans)) {
    const scan = scans[id];
    if (packages.indexOf(scan.packageName) < 0 || !scan.result) {
      continue;
    }
    const found = [];
    const upgrade = scan.result.upgrade || {};
    if (upgrade.recommendedVersion) {
      found.push({ version: String(upgrade.recommendedVersion), why: "fixes " + scan.packageVersion + "'s own advisories" });
    }
    const deprecation = scan.result.deprecation || {};
    if (deprecation.latestVersion && deprecation.latestDeprecated !== true) {
      found.push({ version: String(deprecation.latestVersion), why: "npm latest" });
    }
    for (const item of found) {
      const candidate = scan.packageName + "@" + item.version;
      if (!taken[candidate]) {
        taken[candidate] = true;
        if (scan.packageName !== dependency && item.why === "npm latest") {
          candidates.unshift(candidate + " (" + item.why + ")");
        } else {
          candidates.push(candidate + " (" + item.why + ")");
        }
      }
    }
  }
  return candidates;
}

// Reviews every choice, records the verdicts in the state, and returns the status lines.
function review(state, maxAnswers) {
  const scans = scansById(state);
  state.verdicts = {};
  for (const id of Object.keys(scans)) {
    state.verdicts[id] = rejection(scans[id]);
  }
  state.review = {};
  const lines = ["Answer " + (state.answers + 1) + " of at most " + maxAnswers + "."];
  for (const dependency of state.dependencies) {
    const currentId = dependency.name + "@" + dependency.version;
    const current = scans[currentId];
    const status = statusOf(current);
    const choice = state.choices[dependency.name];
    const choiceId = choice.packageName + "@" + choice.packageVersion;
    const problem = rejection(scans[choiceId]);
    state.review[dependency.name] = { choice: choiceId, status: status, accepted: problem === "", problem: problem };
    if (problem === "") {
      state.lastAccepted[dependency.name] = { packageName: choice.packageName, packageVersion: choice.packageVersion, reason: choice.reason, note: "" };
    }
    const fallback = state.lastAccepted[dependency.name];

    // e.g. "express 4.17.1: acceptable as is (own: 1 MODERATE, 1 LOW, fixed in 4.20.0). Choice: express@4.20.0, accepted (...)."
    let line = dependency.name + " " + dependency.version + ": " + status + " (" + describeFacts(current) + "). Choice: ";
    if (choiceId === currentId) {
      line += "keep " + dependency.version;
    } else if (choice.packageName === dependency.name) {
      line += choiceId;
    } else {
      line += "replace with " + choiceId;
    }
    if (problem !== "") {
      line += ", rejected: " + problem + ".";
      if (fallback) {
        line += " Unless you choose another, " + fallback.packageName + "@" + fallback.packageVersion + ", the last accepted choice, stands.";
      }
    } else if (choiceId !== currentId) {
      line += ", accepted (" + describeFacts(scans[choiceId]) + ").";
    } else {
      line += ", accepted.";
    }
    if (choice.note) {
      line += " Your last answer for it was ignored: " + choice.note + ".";
    }
    const candidates = candidatesFor(state, dependency.name, scans);
    if (candidates.length > 0) {
      line += " Candidates: " + candidates.join(", ") + ".";
    }
    if (status === "must be replaced") {
      line += " You may choose a replacement package.";
    }
    lines.push(line);
  }
  return lines.join("\n");
}

// Puts each rejected choice back to the dependency's last accepted choice, if it had one, and says so
// in its review, e.g. fellBack: "@strapi/strapi@5.60.0 was rejected: its scan had no deps.dev data (...)"
function fallBack(state) {
  for (const dependency of state.dependencies) {
    const review = state.review[dependency.name];
    const fallback = state.lastAccepted[dependency.name];
    if (review.accepted || !fallback) {
      continue;
    }
    state.choices[dependency.name] = fallback;
    state.review[dependency.name] = {
      choice: fallback.packageName + "@" + fallback.packageVersion,
      status: review.status,
      accepted: true,
      problem: "",
      fellBack: review.choice + " was rejected: " + review.problem
    };
  }
}

function nextAction() {
  const state = parseJson($.stateText, null) || startState(parseJson($.dependenciesText, {}));
  let maxAnswers = 3;
  if (typeof $.maxAnswers === "number") {
    maxAnswers = $.maxAnswers;
  }
  state.iterations = (state.iterations || 0) + 1;

  // Scan whatever is queued first, one version per iteration.
  if (state.queue.length > 0) {
    const next = state.queue[0];
    return {
      action: "scan",
      arguments: { packageName: next.packageName, packageVersion: next.packageVersion },
      statusText: "",
      stateText: JSON.stringify(state)
    };
  }

  // Nothing queued: review every choice, then stop or ask the LLM.
  let statusText = review(state, maxAnswers);
  let allAccepted = true;
  for (const dependency of state.dependencies) {
    if (!state.review[dependency.name].accepted) {
      allAccepted = false;
    }
  }
  const last = state.lastAnswer || {};
  let stopReason = "";
  if (state.answers >= 1 && allAccepted) {
    stopReason = "every choice is accepted";
  } else if (state.answers >= maxAnswers) {
    stopReason = "the LLM answered " + maxAnswers + " times";
  } else if (last.usable === true && last.queued === 0) {
    stopReason = "the last answer brought nothing new to scan";
  }
  if (stopReason !== "") {
    // The LLM won't read this review, so its first line says what it is, e.g. "Final review, after 3 answers."
    const lines = statusText.indexOf("\n") >= 0 ? statusText.substring(statusText.indexOf("\n")) : "";
    statusText = "Final review, after " + state.answers + " answer" + (state.answers === 1 ? "" : "s") + "." + lines;
    state.rounds[state.rounds.length - 1].statusText = statusText;
    state.stopReason = stopReason;
    fallBack(state);
    return { action: "stop", statusText: statusText, stateText: JSON.stringify(state) };
  }
  state.rounds[state.rounds.length - 1].statusText = statusText;
  return { action: "propose", statusText: statusText, stateText: JSON.stringify(state) };
}

nextAction();

