inputParameters.expression:
// record_result: runs last in every iteration of agent_loop, before save_state, and adds the result of
// the action next_action picked to the state: a scan's result, or the LLM's answer, checked, with the
// versions it adds queued for a scan. On "stop", it marks the planner done.
//
// Inputs:  $.next           next_action's output: action, arguments and stateText
//          $.toolOutput     call_npm_tool's output, read only when next_action picked "scan"
//          $.toolArguments  call_npm_tool's input arguments, to check the output is this scan's
//          $.answer         propose_versions' answer, read only when next_action picked "propose"
// Output:  stateText, done (true on "stop"), rounds, answers, stopReason
//
// It reads only the branch next_action picked. Inside a loop, a reference to a task that the SWITCH
// skipped in this iteration can return that task's output from an earlier iteration.
//
// An answer is checked: each choice needs an exact version; another package is allowed only for a
// dependency marked "must be replaced"; and a version already rejected can't be chosen again. A
// missing or invalid choice keeps the previous one, with a note that the next status line shows.
//
// Notes on Conductor:
// - The last line calls recordResult(); what it returns becomes the task output.
//   Everything else is inside functions, because a top-level const or let can fail when
//   Conductor reuses a script context.
// - Text is joined with + because Conductor treats a dollar sign followed by a brace in a task
//   input as a workflow reference, which rules out JavaScript template literals.
// - The tool output, the arguments and the answer arrive as Java maps and lists, so lists are read
//   with an index loop. The state arrives as JSON text, so JSON.parse gives plain JavaScript values.

function parseJson(text, fallback) {
  if (!text) {
    return fallback;
  }
  try {
    return JSON.parse(String(text));
  } catch (e) {
    return fallback;
  }
}

// "4.17.1" or "5.0.0-beta.3", but not "^4.17.1", "4.x" or "latest".
function isExactVersion(version) {
  return /^\d+\.\d+\.\d+(-[0-9A-Za-z.-]+)?$/.test(version);
}

// The fields the planner needs from a POST_scan result. The full result also lists every
// dependency's licenses, which the state doesn't need.
function summarizeScan(output) {
  if (!output) {
    return { error: "the tool call failed or returned nothing" };
  }
  let text = "";
  if (output.content && output.content.length > 0) {
    text = String(output.content[0].text || "");
  }
  if (output.isError === true) {
    return { error: text.substring(0, 500) || "the tool reported an error" };
  }
  if (text === "") {
    // A failed optional task still has an output, just no content.
    let detail = "";
    if (output.error) {
      detail = ": " + String(output.error).substring(0, 300);
    }
    return { error: "the tool returned no result" + detail };
  }
  let data = null;
  try {
    data = JSON.parse(text);
  } catch (e) {
    return { error: "the tool's result wasn't JSON: " + text.substring(0, 300) };
  }

  // The /scan route adds a warning when deps.dev or OSV.dev had no data for this version.
  const summary = { advisories: data.advisories || [], upgrade: data.upgrade };
  if (data.warning) {
    summary.warning = data.warning;
  }

  // Whether this version, or the whole package, is deprecated, and npm's newest version, e.g.
  // {"thisVersion": true, "reason": "Bad release. Please use lodash@4.17.21 instead.", "latestVersion": "4.18.1", "latestDeprecated": false}
  if (data.deprecation) {
    summary.deprecation = {
      thisVersion: data.deprecation.thisVersion,
      latestVersion: data.deprecation.latestVersion,
      latestDeprecated: data.deprecation.latestDeprecated
    };
    if (data.deprecation.reason) {
      summary.deprecation.reason = String(data.deprecation.reason).substring(0, 150);
    }
  }

  // Missing data must never read as "no advisories". When a source didn't answer, the scan still
  // reports empty lists and counts of 0, so replace them with a note saying what wasn't checked.
  const sources = data.sources || {};
  if (sources.osv === false) {
    summary.advisories = "unknown: OSV.dev didn't answer, so this version's own advisories weren't checked";
  }
  const deps = data.transitiveDependencies;
  if (sources.dependencyGraph === false || !deps) {
    summary.dependencies = {
      notChecked: "all: deps.dev returned no dependency data for this version, so its dependencies' advisories are unknown, not zero"
    };
  } else {
    // One line per vulnerable dependency, e.g. {"package": "qs@6.7.0", "severity": "1 HIGH, 2 MODERATE", "fixedIn": "6.16.0"}
    const vulnerable = [];
    for (const dep of deps.packagesWithAdvisories || []) {
      vulnerable.push({ package: dep.package, severity: dep.severity, fixedIn: dep.fixedIn || null });
    }
    summary.dependencies = {
      total: deps.total,
      checked: deps.checked,
      advisories: deps.uniqueAdvisoryCount,
      highOrCritical: deps.highOrCriticalAdvisories,
      // Dependencies with a HIGH or CRITICAL advisory that no version fixes, e.g. ["deepmerge@4.3.1"]
      unfixedHighOrCritical: deps.unfixedHighOrCritical || [],
      vulnerable: vulnerable
    };
    if (deps.deprecated && deps.deprecated.count > 0) {
      summary.dependencies.deprecated = deps.deprecated.count;
    }
    // e.g. "199 of 1321: the counts above are incomplete"
    if (deps.checked < deps.total) {
      summary.dependencies.notChecked = (deps.total - deps.checked) + " of " + deps.total + ": the counts above are incomplete";
    }
  }
  return summary;
}

// True if name@version has been scanned or is queued.
function isScannedOrQueued(state, id) {
  for (const round of state.rounds) {
    for (const scan of round.scans) {
      if (scan.packageName + "@" + scan.packageVersion === id) {
        return true;
      }
    }
  }
  for (const item of state.queue) {
    if (item.packageName + "@" + item.packageVersion === id) {
      return true;
    }
  }
  return false;
}

// Checks the LLM's answer against the review next_action stored, updates the choices and queues the
// versions not scanned yet. Returns the answer as recorded in the round.
function applyAnswer(state, rawAnswer) {
  state.answers = (state.answers || 0) + 1;
  let answer = rawAnswer;
  if (typeof answer === "string") {
    answer = parseJson(answer, null);
  }
  const list = answer ? answer.choices : null;
  const usable = !!list && typeof list.length === "number" && list.length > 0;

  // The first choice given for each dependency.
  const given = {};
  if (usable) {
    for (let i = 0; i < list.length; i++) {
      const item = list[i] || {};
      const dependency = String(item.dependency || "").trim();
      if (dependency !== "" && !given[dependency]) {
        given[dependency] = item;
      }
    }
  }

  const recorded = [];
  let queued = 0;
  for (const dependency of state.dependencies) {
    const name = dependency.name;
    const previous = state.choices[name];
    const kept = previous.packageName + "@" + previous.packageVersion;
    const item = given[name];
    if (!item) {
      previous.note = (usable ? "it had no choice" : "the answer wasn't usable JSON") + ", so " + kept + " was kept";
      recorded.push({ dependency: name, ignored: previous.note });
      continue;
    }
    const packageName = String(item.packageName || name).trim();
    const packageVersion = String(item.packageVersion || "").trim();
    const reason = String(item.reason || "").substring(0, 200);
    const id = packageName + "@" + packageVersion;
    const review = state.review[name] || {};
    let problem = "";
    if (!isExactVersion(packageVersion)) {
      problem = "\"" + packageVersion + "\" isn't an exact version";
    } else if (packageName !== name && review.status !== "must be replaced") {
      problem = "another package is allowed only for a dependency marked \"must be replaced\"";
    } else if (state.verdicts[id]) {
      problem = id + " was already rejected: " + state.verdicts[id];
    }
    if (problem !== "") {
      previous.note = id + " was ignored: " + problem + "; " + kept + " was kept";
      recorded.push({ dependency: name, packageName: packageName, packageVersion: packageVersion, reason: reason, ignored: problem });
      continue;
    }
    state.choices[name] = { packageName: packageName, packageVersion: packageVersion, reason: reason, note: "" };
    recorded.push({ dependency: name, packageName: packageName, packageVersion: packageVersion, reason: reason });
    if (!isScannedOrQueued(state, id)) {
      state.queue.push({ packageName: packageName, packageVersion: packageVersion });
      queued++;
    }
  }
  state.lastAnswer = { usable: usable, queued: queued };
  return recorded;
}

function recordResult() {
  const next = $.next || {};
  const state = parseJson(next.stateText, null);
  if (!state) {
    return { stateText: null, done: true, rounds: 0, answers: 0, stopReason: "next_action returned no state" };
  }
  const action = String(next.action || "");
  const round = state.rounds[state.rounds.length - 1];
  let done = false;

  if (action === "scan") {
    const asked = next.arguments || {};
    const packageName = String(asked.packageName);
    const packageVersion = String(asked.packageVersion);
    const id = packageName + "@" + packageVersion;
    const remaining = [];
    for (const item of state.queue) {
      if (item.packageName + "@" + item.packageVersion !== id) {
        remaining.push(item);
      }
    }
    state.queue = remaining;

    // Use call_npm_tool's output only if it was called with these arguments in this iteration.
    const called = $.toolArguments || {};
    let result = null;
    if (String(called.packageName) === packageName && String(called.packageVersion) === packageVersion) {
      result = summarizeScan($.toolOutput);
    } else {
      result = { error: "call_npm_tool's output wasn't for this version, so it wasn't used" };
    }
    round.scans.push({ packageName: packageName, packageVersion: packageVersion, iteration: state.iterations, result: result });
  } else if (action === "propose") {
    round.answer = applyAnswer(state, $.answer);
    state.rounds.push({ round: round.round + 1, scans: [], statusText: "", answer: null });
  } else {
    done = true;
  }

  return {
    stateText: JSON.stringify(state),
    done: done,
    rounds: state.rounds.length,
    answers: state.answers,
    stopReason: state.stopReason || ""
  };
}

recordResult();

// check_recommendations: turns the planner's final choices into recommendations, and builds one
// assess_npm_package sub-workflow per accepted version, for the dynamic fork.
//
// Inputs:  $.stateText         the planner's final state, as JSON text (see next_action): its scans,
//                              its choices, and the last review, which says whether each was accepted
//          $.dependenciesText  the current dependencies, as JSON text, e.g. {"express": "4.17.1"}
// Output:  recommendations     one per current dependency: dependency, currentVersion, currentIssues
//                              (what its scan says is wrong with the current version), action ("keep",
//                              "upgrade", "replace" or "none"), packageName, packageVersion, verified,
//                              problem, assessmentRef, and the recommended version's own advisories:
//                              ownHighOrCritical (a count) and ownSeverity (e.g. "1 MODERATE, 1 LOW"),
//                              so write_plan counts only HIGH or CRITICAL ones as unresolved
//          dynamicTasks, dynamicTasksInput   for assess_recommended_versions (FORK_JOIN_DYNAMIC)
//          mode                "assess" when there's at least one assessment to run, otherwise "none".
//                              assess_if_needed (a SWITCH) runs the dynamic fork only in "assess" mode
//          scanProblem         "" unless most scans failed or had no data; then a warning for the plan
//          issueBanner         the same warning as a markdown quote for the top of the GitHub issue, or ""
//          stoppedBecause      why the planner stopped, e.g. "every choice is accepted"
//
// Notes on Conductor:
// - The last line calls checkRecommendations(); what it returns becomes the task output.
//   Everything else is inside functions, because a top-level const or let can fail when
//   Conductor reuses a script context.
// - Text is joined with + because Conductor treats a dollar sign followed by a brace in a task
//   input as a workflow reference, which rules out JavaScript template literals.
// - Both inputs arrive as JSON text, so JSON.parse gives plain JavaScript values.

function parseJson(text, fallback) {
  if (!text) {
    return fallback;
  }
  try {
    return JSON.parse(text);
  } catch (e) {
    return fallback;
  }
}

// Every scan in the state, as a list of {tool, packageName, packageVersion, result}, in the order they ran.
function listScans(state) {
  const scans = [];
  for (const round of state.rounds || []) {
    for (const scan of round.scans || []) {
      scans.push({ tool: "POST_scan", packageName: scan.packageName, packageVersion: scan.packageVersion, result: scan.result });
    }
  }
  return scans;
}

// The ledger entry for a scan of packageName@packageVersion, or null.
function findScan(ledger, packageName, packageVersion) {
  for (const entry of ledger) {
    if (entry.tool === "POST_scan" && entry.packageName === packageName && entry.packageVersion === packageVersion) {
      return entry;
    }
  }
  return null;
}

// Why a scan can't back a recommendation, or "" if it can. A scan without deps.dev data looks the
// same whether the version is too new for deps.dev, doesn't exist, or deps.dev is failing, so it says all three.
function whyUnverified(scan) {
  if (!scan) {
    return "the ledger has no scan of this version";
  }
  const result = scan.result || {};
  if (result.error) {
    return "its scan failed";
  }
  if (result.dependencies && result.dependencies.total === undefined) {
    return "its scan had no deps.dev data (the version may be too new for deps.dev, or may not exist, or deps.dev may be failing)";
  }
  if (typeof result.advisories === "string") {
    return "its scan had no OSV.dev data";
  }
  if (result.warning) {
    return "its scan came back with a warning: " + result.warning;
  }
  return "";
}

// What the current version's scan says is wrong with it, so the plan can say why it changes,
// e.g. ["request is deprecated", "an advisory on request has no fix"]. Empty if nothing, or no scan.
function describeCurrentIssues(ledger, dependency, currentVersion) {
  const issues = [];
  const scan = findScan(ledger, dependency, currentVersion);
  if (!scan || !scan.result) {
    return issues;
  }
  const deprecation = scan.result.deprecation || {};
  if (deprecation.latestDeprecated === true) {
    issues.push(dependency + " is deprecated");
  } else if (deprecation.thisVersion === true) {
    issues.push(dependency + "@" + currentVersion + " is deprecated");
  }
  const upgrade = scan.result.upgrade || {};
  if (upgrade.status === "no_fix" || upgrade.status === "no_single_fix") {
    issues.push("an advisory on " + dependency + " has no fix");
  }
  return issues;
}

// The scanned version's own advisories: how many are HIGH or CRITICAL, and all of them by severity,
// e.g. {highOrCritical: 0, severity: "1 MODERATE, 1 LOW"}. Null counts if the scan has no OSV.dev data.
function describeOwnAdvisories(scan) {
  const advisories = scan && scan.result ? scan.result.advisories : null;
  if (!advisories || typeof advisories === "string") {
    return { highOrCritical: null, severity: "" };
  }
  const order = ["CRITICAL", "HIGH", "MODERATE", "LOW"];
  const counts = {};
  let other = 0;
  for (const advisory of advisories) {
    const severity = String(advisory.severity || "").toUpperCase();
    if (order.indexOf(severity) >= 0) {
      counts[severity] = (counts[severity] || 0) + 1;
    } else {
      other++;
    }
  }
  const parts = [];
  for (const severity of order) {
    if (counts[severity]) {
      parts.push(counts[severity] + " " + severity);
    }
  }
  if (other > 0) {
    parts.push(other + " of unknown severity");
  }
  return { highOrCritical: (counts.CRITICAL || 0) + (counts.HIGH || 0), severity: parts.join(", ") };
}

// A warning when most scans failed or had no data, which usually means a data source is failing,
// not that the packages are clean. "" otherwise.
// e.g. "5 of 7 scans in this run failed or came back without data from deps.dev or OSV.dev, ..."
function describeScanProblem(ledger) {
  let scans = 0;
  let unusable = 0;
  for (const entry of ledger) {
    if (entry.tool === "POST_scan") {
      scans++;
      if (whyUnverified(entry) !== "") {
        unusable++;
      }
    }
  }
  if (scans === 0 || unusable * 2 <= scans) {
    return "";
  }
  let which = unusable + " of " + scans + " scans in this run";
  if (unusable === scans) {
    which = "Every scan in this run";
  }
  return which + " failed or came back without data from deps.dev or OSV.dev, so those versions couldn't be " +
    "verified or assessed. This usually means a data source is failing, not that the packages are clean: " +
    "check the deps_dev Remote Service and this run's scan_npm_package executions.";
}

function checkRecommendations() {
  const state = parseJson($.stateText, {});
  const ledger = listScans(state);
  const dependencies = parseJson($.dependenciesText, {});
  const choices = state.choices || {};
  const reviews = state.review || {};

  const recommendations = [];
  const dynamicTasks = [];
  const dynamicTasksInput = {};
  for (const dependency of Object.keys(dependencies)) {
    const currentVersion = String(dependencies[dependency]);
    const pick = choices[dependency] || null;

    // e.g. {dependency: "express", currentVersion: "4.17.1", action: "upgrade", packageName: "express", packageVersion: "4.20.0", ...}
    const recommendation = {
      dependency: dependency,
      currentVersion: currentVersion,
      currentIssues: describeCurrentIssues(ledger, dependency, currentVersion),
      action: "none",
      packageName: null,
      packageVersion: null,
      verified: false,
      problem: "",
      assessmentRef: null,
      ownHighOrCritical: null,
      ownSeverity: ""
    };
    recommendations.push(recommendation);

    // Every dependency starts with its current version as the choice, so this means a broken state.
    if (pick === null || !pick.packageName || !pick.packageVersion) {
      recommendation.problem = "the planner didn't recommend a version";
      continue;
    }
    recommendation.packageName = pick.packageName;
    recommendation.packageVersion = pick.packageVersion;
    const own = describeOwnAdvisories(findScan(ledger, pick.packageName, pick.packageVersion));
    recommendation.ownHighOrCritical = own.highOrCritical;
    recommendation.ownSeverity = own.severity;

    // The action follows from what was chosen.
    if (pick.packageName !== dependency) {
      recommendation.action = "replace";
    } else if (pick.packageVersion === currentVersion) {
      recommendation.action = "keep";
    } else {
      recommendation.action = "upgrade";
    }

    // Only a choice the last review accepted is assessed. Its scan is checked again, in case the state
    // is inconsistent. A choice without a matching review means the loop stopped at its iteration cap.
    const review = reviews[dependency];
    let problem = "";
    if (!review || review.choice !== pick.packageName + "@" + pick.packageVersion) {
      problem = "it wasn't reviewed before the planner stopped";
    } else if (review.accepted !== true) {
      problem = review.problem || "it was rejected";
    } else {
      problem = whyUnverified(findScan(ledger, pick.packageName, pick.packageVersion));
    }
    if (problem !== "") {
      recommendation.problem = problem;
      continue;
    }
    recommendation.verified = true;

    // e.g. "assess_rec_1". Optional, so one failed assessment doesn't stop the others or the plan.
    const ref = "assess_rec_" + (dynamicTasks.length + 1);
    recommendation.assessmentRef = ref;
    dynamicTasks.push({
      name: "assess_npm_package",
      taskReferenceName: ref,
      type: "SUB_WORKFLOW",
      optional: true,
      subWorkflowParam: { name: "assess_npm_package" }
    });
    dynamicTasksInput[ref] = { packageName: pick.packageName, packageVersion: pick.packageVersion };
  }

  // "none" when nothing passed the checks. assess_if_needed then skips the dynamic fork rather than
  // start it with an empty task list, which might fail the whole run. The plan is still written,
  // and says why each dependency wasn't assessed.
  let mode = "none";
  if (dynamicTasks.length > 0) {
    mode = "assess";
  }

  // The banner goes above the plan in the GitHub issue, so the warning shows even if the LLM's
  // summary leaves it out.
  const scanProblem = describeScanProblem(ledger);
  let issueBanner = "";
  if (scanProblem !== "") {
    issueBanner = "> **Warning:** " + scanProblem + "\n\n";
  }

  // e.g. "every choice is accepted". next_action sets it when it stops the loop.
  let stoppedBecause = state.stopReason || "";
  if (stoppedBecause === "") {
    stoppedBecause = "the loop reached its iteration cap after " + (state.iterations || 0) + " iterations";
  }

  return {
    recommendations: recommendations,
    dynamicTasks: dynamicTasks,
    dynamicTasksInput: dynamicTasksInput,
    mode: mode,
    scanProblem: scanProblem,
    issueBanner: issueBanner,
    stoppedBecause: stoppedBecause
  };
}

checkRecommendations();

// write_plan: works out whether the goal is reached, and writes the body of the plan: an overview table
// with one row per current dependency, then the full brief of each assessed version. write_plan_summary
// (the LLM) then writes a short summary from the goal status and the overview alone, so it can't
// contradict them, and finish_plan puts the goal status, the summary and the body together.
//
// Inputs:  $.recommendationsText  the recommendations with their assessments, as JSON text,
//                                 from summarize_assessments
// Output:  goal                   whether the goal is reached, e.g. "reached once a reviewer accepts express@4.20.0"
//          overview               the table, e.g. the rows
//          | request | 2.88.2 | Replace with got@11.8.5 (request is deprecated and an advisory on request has no fix; needs code changes) |
//            ADOPT, approved by policy |
//          | express | 4.17.1 | Upgrade to 4.20.0, and override body-parser to 1.20.9, path-to-regexp to 0.1.13 |
//            ADOPT_WITH_CONDITIONS, needs a reviewer: 10 known advisories (0 on the package, 10 in dependencies), 3 of them high or critical |
//          planBody               "## Overview", the table, "## Assessments" and one brief per assessed version
//
// The override rule: each dependency of the recommended version with a HIGH or CRITICAL advisory is
// pinned to its fixed version, and one with no fix is listed as unresolved. An assessment lists its 15
// most severe vulnerable dependencies, so a version with more than 15 HIGH or CRITICAL ones lists only those.
//
// The goal rule: it's reached only if every dependency has a verified recommendation that was assessed,
// not rejected, and has nothing unresolved: no HIGH or CRITICAL advisory of its own, and none in a
// dependency without a fix. That's the planner's rule too (next_action). The overrides fix the
// dependencies' HIGH or CRITICAL advisories, so a version that needs only a reviewer's approval still
// reaches it, once approved. Its own MODERATE or LOW advisories are noted in the row, not counted.
//
// Notes on Conductor:
// - The last line calls writePlan(); what it returns becomes the task output.
//   Everything else is inside functions, because a top-level const or let can fail when
//   Conductor reuses a script context.
// - Text is joined with + because Conductor treats a dollar sign followed by a brace in a task
//   input as a workflow reference, which rules out JavaScript template literals.
// - The input arrives as JSON text, so JSON.parse gives plain JavaScript values.

// Keeps a table cell on one line, and stops a "|" in the text from starting a new cell.
function cell(text) {
  return String(text).replace(/\|/g, "\\|").replace(/\s*\n\s*/g, " ");
}

// "qs@6.7.0" -> "qs", "@babel/core@7.0.0" -> "@babel/core"
function nameOf(packageRef) {
  return packageRef.substring(0, packageRef.lastIndexOf("@"));
}

// True if version a is newer than version b, comparing "4.17.21"-style numbers part by part.
function isNewer(a, b) {
  const partsA = String(a).split("-")[0].split(".");
  const partsB = String(b).split("-")[0].split(".");
  for (let i = 0; i < Math.max(partsA.length, partsB.length); i++) {
    const numberA = parseInt(partsA[i], 10) || 0;
    const numberB = parseInt(partsB[i], 10) || 0;
    if (numberA !== numberB) {
      return numberA > numberB;
    }
  }
  return false;
}

// The recommended action, why the current version changes, the overrides and unresolved risks its
// assessment shows, and whether anything is unresolved,
// e.g. {text: "Upgrade to 4.20.0, and override body-parser to 1.20.9, ...", unresolved: false}
function describeAction(recommendation) {
  if (!recommendation.verified) {
    // e.g. "No verified recommendation (lodash@4.18.0: its scan had no deps.dev data (...))"
    let detail = recommendation.problem;
    if (recommendation.packageName) {
      detail = recommendation.packageName + "@" + recommendation.packageVersion + ": " + detail;
    }
    return { text: "No verified recommendation (" + detail + ")", unresolved: false };
  }

  // Why it changes, from the current version's scan, e.g. "request is deprecated and an advisory on
  // request has no fix", and whether a replacement needs code changes.
  const notes = [];
  const issues = recommendation.currentIssues || [];
  if (issues.length > 0) {
    notes.push(issues.join(" and "));
  }
  let text = "Upgrade to " + recommendation.packageVersion;
  if (recommendation.action === "keep") {
    text = "Keep " + recommendation.packageVersion;
  } else if (recommendation.action === "replace") {
    text = "Replace with " + recommendation.packageName + "@" + recommendation.packageVersion;
    notes.push("needs code changes");
  }
  if (notes.length > 0) {
    text += " (" + notes.join("; ") + ")";
  }
  const assessment = recommendation.assessment;
  if (!assessment || assessment.error) {
    return { text: text, unresolved: false };
  }

  // One override per dependency name, at the highest fixed version any of its copies needs.
  const fixedVersions = {};
  const newMajor = {};
  const risks = [];
  for (const dep of assessment.vulnerableDependencies) {
    if (dep.highOrCritical > 0) {
      if (dep.fixedIn) {
        const name = nameOf(dep.package);
        if (!fixedVersions[name] || isNewer(dep.fixedIn, fixedVersions[name])) {
          fixedVersions[name] = dep.fixedIn;
        }
        if (/new major/.test(String(dep.fix))) {
          newMajor[name] = true;
        }
      } else {
        risks.push(dep.package + " has a HIGH or CRITICAL advisory with no fix");
      }
    }
  }
  // e.g. "override nodemailer to 10.0.10 (new major), dompurify to 3.4.17"
  const overrides = [];
  for (const name of Object.keys(fixedVersions)) {
    let override = name + " to " + fixedVersions[name];
    if (newMajor[name]) {
      override += " (new major)";
    }
    overrides.push(override);
  }
  if (overrides.length > 0) {
    text += ", and override " + overrides.join(", ");
  }

  // Advisories on the recommended version itself. Only HIGH or CRITICAL ones are unresolved; lower
  // ones get a note, e.g. "Optional: its own advisories (1 MODERATE, 1 LOW) are fixed in 4.20.0".
  // Without the count (ownHighOrCritical is null), they're treated as HIGH, to be safe.
  const fixable = assessment.upgradeStatus === "same_major" || assessment.upgradeStatus === "major_upgrade";
  const unfixable = assessment.upgradeStatus === "no_fix" || assessment.upgradeStatus === "no_single_fix";
  const minorOnly = recommendation.ownHighOrCritical === 0;
  let ownNote = "";
  if (fixable && minorOnly) {
    ownNote = "Optional: its own advisories (" + recommendation.ownSeverity + ") are fixed in " + assessment.recommendedVersion;
  } else if (fixable) {
    risks.push("its own advisories are fixed only in " + assessment.recommendedVersion);
  } else if (unfixable && minorOnly && assessment.upgradeStatus === "no_fix") {
    ownNote = "Also: one of its own advisories (" + recommendation.ownSeverity + ") has no fix yet";
  } else if (unfixable && minorOnly) {
    ownNote = "Also: no single version fixes all its own advisories (" + recommendation.ownSeverity + ")";
  } else if (unfixable) {
    risks.push("an advisory on the package itself has no fix");
  }
  if (risks.length > 0) {
    text += ". Unresolved: " + risks.join("; ");
  }
  if (ownNote !== "") {
    text += ". " + ownNote;
  }
  return { text: text, unresolved: risks.length > 0 };
}

// What the assessment decided, e.g. "ADOPT_WITH_CONDITIONS, needs a reviewer: 10 known advisories (...)"
function describeAssessment(recommendation) {
  const assessment = recommendation.assessment;
  if (!recommendation.verified || !assessment) {
    return "Not assessed";
  }
  if (assessment.error) {
    let text = "Not assessed: the assessment failed";
    if (assessment.workflowId) {
      text += " (run " + assessment.workflowId + ")";
    }
    return text;
  }
  if (assessment.route === "AUTO_APPROVE") {
    return assessment.verdict + ", approved by policy";
  }
  if (assessment.route === "AUTO_REJECT") {
    return assessment.verdict + ", rejected: " + (assessment.rejectReasons[0] || "see its brief");
  }
  // Human review: up to two reasons, leaving out the AI verdict, which is already shown.
  const reasons = [];
  for (const reason of assessment.routeReasons) {
    if (!/^AI verdict is /.test(reason) && reasons.length < 2) {
      reasons.push(reason);
    }
  }
  if (reasons.length > 0) {
    return assessment.verdict + ", needs a reviewer: " + reasons.join("; ");
  }
  // The AI verdict is the only reason, so say what it means.
  if (assessment.verdict === "ADOPT_WITH_CONDITIONS") {
    return assessment.verdict + ", needs a reviewer to accept the AI's conditions (see its brief)";
  }
  if (assessment.verdict === "AVOID") {
    return assessment.verdict + ", needs a reviewer: the AI advises against it (see its brief)";
  }
  return assessment.verdict + ", needs a reviewer: the AI's answer couldn't be used (see its brief)";
}

// Whether the goal is reached (see the goal rule above), from each row's recommendation and whether
// it has anything unresolved, e.g. "reached once a reviewer accepts express@4.20.0" or
// "not reached: lodash has no verified recommendation"
function describeGoal(rows) {
  if (rows.length === 0) {
    return "not reached: nothing was recommended";
  }
  const problems = [];
  const reviews = [];
  for (const row of rows) {
    const recommendation = row.recommendation;
    const version = recommendation.packageName + "@" + recommendation.packageVersion;
    const assessment = recommendation.assessment;
    if (!recommendation.verified) {
      problems.push(recommendation.dependency + " has no verified recommendation");
    } else if (!assessment || assessment.error) {
      problems.push(version + " wasn't assessed");
    } else if (assessment.route === "AUTO_REJECT") {
      problems.push(version + " was rejected");
    } else if (row.unresolved) {
      problems.push(version + " has unresolved risks");
    } else if (assessment.route === "HUMAN_REVIEW") {
      reviews.push(version);
    }
  }
  if (problems.length > 0) {
    return "not reached: " + problems.join("; ");
  }
  if (reviews.length === 0) {
    return "reached: every recommendation was approved by policy";
  }
  // e.g. "express@4.20.0", "a@1.0.0 and b@2.0.0", "a@1.0.0, b@2.0.0 and c@3.0.0"
  let names = reviews[reviews.length - 1];
  if (reviews.length > 1) {
    names = reviews.slice(0, -1).join(", ") + " and " + names;
  }
  return "reached once a reviewer accepts " + names;
}

function writePlan() {
  let recommendations = [];
  try {
    recommendations = JSON.parse($.recommendationsText || "[]");
  } catch (e) {
    recommendations = [];
  }

  const rows = [
    "| Dependency | Current | Recommended action | Assessment |",
    "| --- | --- | --- | --- |"
  ];
  const briefs = [];
  const goalRows = [];
  let length = 0;
  for (const recommendation of recommendations) {
    const action = describeAction(recommendation);
    goalRows.push({ recommendation: recommendation, unresolved: action.unresolved });
    const cells = [
      recommendation.dependency,
      recommendation.currentVersion,
      action.text,
      describeAssessment(recommendation)
    ];
    const escaped = [];
    for (const text of cells) {
      escaped.push(cell(text));
    }
    rows.push("| " + escaped.join(" | ") + " |");

    // Each assessed version's brief, under its own heading. GitHub caps an issue at 65,536 characters,
    // so past 50,000 a brief is replaced by a pointer to its run.
    const assessment = recommendation.assessment;
    if (assessment && assessment.briefMarkdown) {
      let brief = assessment.briefMarkdown;
      if (length + brief.length > 50000) {
        brief = "The brief is left out for length; see assessment run " + assessment.workflowId + ".";
      }
      length += brief.length;
      briefs.push("### " + recommendation.packageName + "@" + recommendation.packageVersion + "\n\n" + brief);
    }
  }

  const overview = rows.join("\n");
  let assessed = briefs.join("\n\n");
  if (briefs.length === 0) {
    assessed = "No version was assessed.";
  }
  // Computed, never the LLM's. finish_plan puts it at the top of the plan.
  return {
    goal: describeGoal(goalRows),
    overview: overview,
    planBody: "## Overview\n\n" + overview + "\n\n## Assessments\n\n" + assessed
  };
}

writePlan();

