inputParameters.expression:
// finish_plan: puts the plan together: write_plan's goal status, the LLM's summary, then write_plan's
// overview table and the assessment briefs. Only the summary's first paragraph of plain sentences is
// kept, so the overview appears once, however the LLM formats its answer (one run repeated the table
// and invented a section per package).
//
// Inputs:  $.goal       from write_plan, e.g. "reached once a reviewer accepts express@4.20.0"
//          $.written    write_plan_summary's answer: {summary}
//          $.planBody   from write_plan: "## Overview", the table, "## Assessments" and the briefs
// Output:  planMarkdown "## Summary", the goal status, the paragraph, then planBody
//
// Notes on Conductor:
// - The last line calls finishPlan(); what it returns becomes the task output.
//   Everything else is inside functions, because a top-level const or let can fail when
//   Conductor reuses a script context.
// - Text is joined with + because Conductor treats a dollar sign followed by a brace in a task
//   input as a workflow reference, which rules out JavaScript template literals.

// The summary text, whether the model answered with {summary}, JSON text, or plain text.
function readSummary(written) {
  let value = written;
  if (typeof value === "string") {
    try {
      value = JSON.parse(value);
    } catch (e) {
      value = { summary: value };
    }
  }
  if (!value || !value.summary) {
    return "";
  }
  return String(value.summary);
}

// The first paragraph of plain sentences. Table, heading and list lines are skipped, and the
// paragraph ends at the first blank line or the first such line after it starts.
function firstParagraph(text) {
  const kept = [];
  for (const line of text.split("\n")) {
    const trimmed = line.trim();
    const formatting = trimmed === "" || /^(\||#|[-*+] |\d+[.)] )/.test(trimmed);
    if (formatting && kept.length > 0) {
      break;
    }
    if (!formatting) {
      kept.push(trimmed);
    }
  }
  return kept.join(" ").substring(0, 1500);
}

function finishPlan() {
  let summary = firstParagraph(readSummary($.written));
  if (summary === "") {
    summary = "The model did not return a summary.";
  }
  // e.g. "**Goal status:** reached once a reviewer accepts express@4.20.0", shown once, at the top
  const goal = "**Goal status:** " + String($.goal || "unknown");
  return { planMarkdown: "## Summary\n\n" + goal + "\n\n" + summary + "\n\n" + String($.planBody || "") };
}

finishPlan();

